import { useState } from "react";
import { Calendar, Upload, User, FileText } from "lucide-react";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";

export default function UploadScan() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: "",
    patientId: "",
    gender: "Female",
    age: "",
    date: "",
    image: null,
    scanType: "Chest X-ray"
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });
  const handleImage = (e) => e.target.files && setFormData({ ...formData, image: e.target.files[0] });

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.image) return alert("Please upload an image");

    const data = new FormData();
    data.append("image", formData.image);
    data.append("name", formData.name);
    data.append("patientId", formData.patientId);
    data.append("gender", formData.gender);
    data.append("age", formData.age);
    data.append("date", formData.date);
    data.append("scanType", formData.scanType);

    try {
      setLoading(true);
      const res = await axios.post("http://localhost:5000/api/upload", data, {
        headers: { "Content-Type": "multipart/form-data" }
      });
      alert(res.data.message);
      navigate("/results"); // redirect to results page
    } catch (err) {
      console.error(err);
      alert("Upload failed!");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-cyan-900 p-6">
      <h1 className="text-white text-2xl mb-4">Upload Patient Scan</h1>
      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Left: Image Upload */}
        <div className="bg-gray-800 p-6 rounded-2xl">
          <input type="file" accept="image/*" className="hidden" id="imageUpload" onChange={handleImage} />
          <div
            onClick={() => document.getElementById("imageUpload").click()}
            className="cursor-pointer border-2 border-dashed border-gray-600 rounded-2xl p-8 flex flex-col items-center justify-center min-h-[300px]"
          >
            {formData.image ? (
              <img src={URL.createObjectURL(formData.image)} alt="scan" className="max-h-60 rounded-lg" />
            ) : (
              <>
                <Upload className="h-16 w-16 text-gray-400 mb-2" />
                <p className="text-white">Click or drag to upload</p>
              </>
            )}
          </div>
        </div>

        {/* Right: Patient Info */}
        <div className="bg-sky-100 p-6 rounded-2xl">
          <User className="h-6 w-6 text-gray-700 mb-2" />
          <h2 className="text-gray-800 font-bold mb-4">Patient Information</h2>

          <input name="name" placeholder="Name" value={formData.name} onChange={handleChange} className="mb-3 w-full p-2 rounded border" required />
          <input name="patientId" placeholder="Patient ID" value={formData.patientId} onChange={handleChange} className="mb-3 w-full p-2 rounded border" required />
          <input name="age" placeholder="Age" value={formData.age} onChange={handleChange} className="mb-3 w-full p-2 rounded border" required />

          <select name="gender" value={formData.gender} onChange={handleChange} className="mb-3 w-full p-2 rounded border">
            <option>Female</option>
            <option>Male</option>
            <option>Other</option>
          </select>

          <input type="date" name="date" value={formData.date} onChange={handleChange} className="mb-3 w-full p-2 rounded border" required />

          <select name="scanType" value={formData.scanType} onChange={handleChange} className="mb-3 w-full p-2 rounded border">
            <option>Chest X-ray</option>
            <option>Computed Tomography (CT)</option>
          </select>

          <button type="submit" disabled={loading} className="w-full bg-green-500 text-white py-2 rounded font-semibold hover:bg-green-600">
            {loading ? "Uploading..." : "Upload Scan"}
          </button>
        </div>
      </form>
    </div>
  );
}
